                    nibble = read(player.POSITION_Y, 2) & 0xF
                    c, i = _S12_NIBBLE_HEAD
                    cycles += c
                    instructions += i
                    c, i = _S12_NIBBLE_BEQ[nibble == 0]
                    cycles += c
                    instructions += i
                    if nibble != 0:
                        c, i = _S12_NIBBLE_TEST
                        cycles += c
                        instructions += i
                        blocked = read((address + 0x181) & 0xFFFFFF, 1) == 1
                        c, i = _S12_NIBBLE_BEQ2[blocked]
                        cycles += c
                        instructions += i
